<template>
  <v-dialog v-model="internalDialogVisible" persistent max-width="500" class="top-dialog">
    <v-card>
      <v-card-title>Enter Call Status</v-card-title>
      <v-card-text>
        <textarea v-model="internalInteraction_" placeholder="Interaction" class="e-input bordered-input" rows="3"></textarea>
      </v-card-text>
      <v-card-actions class="d-flex justify-space-between">
        <v-container class="pa-0">
          <!-- WhatsApp Section -->
          <v-row>
            <v-col cols="3" v-for="n in 5" :key="`wp${n}`">
              <v-btn v-if="n === 1" text class="bordered-btn" @click="confirmStatus2('wp')">WP</v-btn>
              <v-btn v-else text class="bordered-btn" @click="confirmStatus2(`wp${n-1}`)">WP{{n-1}}</v-btn>
            </v-col>
          </v-row>

          <!-- Primary Status Buttons -->
          <v-row>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('dnc')">DNC</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('wnb')">Wrong #</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('ni')">NI</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('fup')">FUP</v-btn>
            </v-col>
          </v-row>

          <!-- Property Status Buttons -->
          <v-row>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('cv')">CV</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('cvt')">CVT</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('cls')">CLS</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('wtr')">WTR</v-btn>
            </v-col>
          </v-row>

          <!-- Financial Status Buttons -->
          <v-row>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('wts')">WTS</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('wtb')">WTB</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('ftr')">Future</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('tnt')">Tenanted</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('eg')">EG</v-btn>
            </v-col>
          </v-row>

          <!-- Contact Status Buttons -->
          <v-row>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('cbr')">CBR</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('nr')">NR</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('nis')">NIS</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('vcm')">VCM</v-btn>
            </v-col>
          </v-row>

          <!-- Final Actions -->
          <v-row>
            <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('so')">SO</v-btn>
            </v-col>
            <v-col cols="3">
              <v-btn text class="bordered-btn success" @click="confirmStatus2('qualify')">Qualify</v-btn>
            </v-col>
            <!-- <v-col cols="3">
              <v-btn text class="bordered-btn" @click="confirmStatus2('ok')">OK</v-btn>
            </v-col> -->
            <v-col cols="3">
              <v-btn text color="red" class="bordered-btn" @click="closeDialog">Cancel</v-btn>
            </v-col>
          </v-row>
        </v-container>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
import { ref, watch, defineComponent } from 'vue';

const statusMapping = {
  "dnc": { rating: 1, interaction: "Do not call" },
  "wnb": { rating: 1, interaction: "Wrong Number" },
  "wp": { rating: 2, interaction: "whatsapp send" },
  "wp1": { rating: 2, interaction: "whatsapp send 1" },
  "wp2": { rating: 2, interaction: "whatsapp send 2" },
  "wp3": { rating: 2, interaction: "whatsapp send 3" },
  "wp4": { rating: 2, interaction: "whatsapp send 4" },
  "fup": { rating: 4, interaction: "" },
  "cv": { rating: 5, interaction: "cv" },
  "cvt": { rating: 6, interaction: "cvt" },
  "cls": { rating: 7, interaction: "cls" },
  "wtr": { rating: 8, interaction: "wtr" },
  "wts": { rating: 9, interaction: "wts" },
  "wtb": { rating: 10, interaction: "wtb" },
  "ftr": { rating: 11, interaction: "future" },
  "tnt": { rating: 11, interaction: "tenanted" },
  "ni": { rating: 20, interaction: "not interested" },
  "cbr": { rating: null, interaction: "" },
  "eg": { rating: null, interaction: "" },
  "vcm": { rating: null, interaction: "" },
  "nis": { rating: null, interaction: "" },
  "nr": { rating: null, interaction: "" },
  "so": { rating: null, interaction: "" }
};

export default defineComponent({
  name: 'statusDialog',
  props: {
    showDialog: { type: Boolean, required: true },
    selectedStatus: { type: String, default: '' },
    interaction: { type: String, default: '' },
    rating: { type: Number, default: 0 }
  },
  emits: ['update:showDialog', 'updateStatus'],
  setup(props, { emit }) {
    const internalDialogVisible = ref(props.showDialog);
    const internalSelectedStatus = ref(props.selectedStatus);
    const internalInteraction = ref(props.interaction);
    const internalInteraction_ = ref("");
    const internalRating = ref(props.rating);

    const confirmStatus2 = (cm) => {
      const now = new Date();
      const formattedDateTime = `(${now.getDate()}/${now.getMonth() + 1} ${now.getHours() % 12 || 12}${now.getHours() >= 12 ? 'P' : 'A'}) `;

      switch (cm) {
        case "ok":
          if (!internalInteraction_.value.includes(".") && internalInteraction_.value) {
            internalInteraction_.value += ".";
          }
          break;
        case "fpi":
          cm = "fp";
          if (!internalInteraction_.value.includes(".")) {
            internalInteraction_.value += ".";
          }
          break;
        case "niw":
          cm = "wnb";
          break;
        case "qualify":
          internalRating.value = 4;
          if (!internalInteraction_.value.includes(".")) {
            internalInteraction_.value += ".";
          }
          break;
      }

      if (statusMapping[cm]) {
        internalSelectedStatus.value = cm;
        internalInteraction_.value = statusMapping[cm].interaction;
        internalRating.value = statusMapping[cm].rating;
      } else {
        internalSelectedStatus.value = cm;
        internalInteraction_.value = "";
        internalRating.value = null;
      }

      emit('updateStatus', 
        internalSelectedStatus.value,
        `${formattedDateTime}${internalInteraction_.value}\n${internalInteraction.value}`
      );
      closeDialog();
    };

    const closeDialog = () => {
      internalDialogVisible.value = false;
    };

    watch(() => props.showDialog, (newVal) => {
      internalDialogVisible.value = newVal;
    });

    watch(() => props.interaction, (newVal) => {
      internalInteraction.value = newVal;
    });

    watch(() => props.rating, (newVal) => {
      internalRating.value = newVal;
    });

    watch(() => props.selectedStatus, (newVal) => {
      internalSelectedStatus.value = newVal;
    });

    watch(internalDialogVisible, (newVal) => {
      emit('update:showDialog', newVal);
    });

    return {
      internalDialogVisible,
      internalSelectedStatus,
      internalInteraction,
      internalInteraction_,
      internalRating,
      confirmStatus2,
      closeDialog
    };
  }
});
</script>

<style scoped>
.bordered-input {
  border: 1px solid #ccc;
  border-radius: 5px;
  padding: 8px;
  width: 100%;
  box-sizing: border-box;
  resize: vertical;
  font-family: inherit;
  font-size: inherit;
}

.bordered-input:hover { border-color: #1976d2; }
.bordered-input:focus {
  border-color: #1976d2;
  outline: none;
  box-shadow: 0 0 4px #1976d2;
}

.bordered-btn {
  border: 1px solid #ccc !important;
  border-radius: 5px;
  padding: 8px;
  background-color: transparent;
}

.bordered-btn:hover { border-color: #1976d2 !important; }
.top-dialog { margin-top: 0 !important; }
.top-dialog .v-dialog {
  margin-top: 0 !important;
  position: fixed !important;
  top: 160px !important;
}
</style>