<template>
  <div id="app">
    <h1>Voice and Text Synchronization</h1>
    <div class="button-group">
      <button 
        v-for="(voice, index) in voices" 
        :key="index"
        @click="switchVoice(index)"
        :class="{ active: currentVoiceIndex === index }"
      >
        {{ voice.name }}
      </button>
    </div>
    <div class="voice-text-sync">
      <div 
        v-for="(segment, index) in currentVoice.textSegments" 
        :key="index"
        :class="{ 'highlighted': index === highlightedSegment }"
      >
        <div class="segment-content">
          <span>{{ segment.text }}</span>
          <button @click="toggleAudio(index)">{{ segment.isPlaying ? 'Stop' : 'Play' }}</button>
        </div>
      </div>
    </div>
    <audio ref="audioPlayer" style="display: none;"></audio>
  </div>
</template>

<script>
export default {
  name: "App",
  data() {
    return {
      currentVoiceIndex: 0,
      highlightedSegment: -1,
      voices: [
        {
          name: "Alvin",
          textSegments: [
            {
              text: "Hi Sir, my name is Alvin, property negotiator,",
              audioSrc: "https://res.cloudinary.com/alvin-tan/video/upload/v1733799543/sound/vpyi2e3wisexaln5w7dv.mp3",
              isPlaying: false, // Track play state
            },
            {
              text: "and I specialize in Parklane property, may I know if your unit is for sale or for rent?",
              audioSrc: "https://res.cloudinary.com/alvin-tan/video/upload/v1733799543/sound/vpyi2e3wisexaln5w7dv.mp3",
              isPlaying: false,
            },
            {
              text: "We have interested buyers for your unit.",
              audioSrc: "https://res.cloudinary.com/alvin-tan/video/upload/v1733799543/sound/vpyi2e3wisexaln5w7dv.mp3",
              isPlaying: false,
            },
          ],
        },
        {
          name: "Alyssa",
          textSegments: [
            {
              text: "Hi Sir, Alyssa here,",
              audioSrc: "https://res.cloudinary.com/alvin-tan/video/upload/v1734519523/sound/alyssa_2.mp3",
              isPlaying: false,
            },
            {
              text: "May I know if you are interested in renting out or selling your Parklane OUG unit?",
              audioSrc: "https://res.cloudinary.com/alvin-tan/video/upload/v1734519523/sound/alyssa_2.mp3",
              isPlaying: false,
            },
            {
              text: "We have potential customers who are interested.",
              audioSrc: "https://res.cloudinary.com/alvin-tan/video/upload/v1734519523/sound/alyssa_2.mp3",
              isPlaying: false,
            },
          ],
        },
        {
          name: "Ashton",
          textSegments: [
            {
              text: "Hi Sir, Ashton here, May I know if you are interested in renting out or selling your Parklane OUG unit? We have potential customers who are interested",
              audioSrc: 'https://res.cloudinary.com/alvin-tan/video/upload/v1734522656/sound/Ashton_2.mp3',
              isPlaying: false,
            },
            {
              text: "Hey, How are you doing today",
              audioSrc: "https://res.cloudinary.com/alvin-tan/video/upload/v1734946510/sound/bkz4qov2p1xhhpzxdtqc.mp3",
              isPlaying: false,
            },
            {
              text: "The Reason I call you is to find out whether your Parklane unit is available for sales or for rent, we got ready customer",
              audioSrc: "https://res.cloudinary.com/alvin-tan/video/upload/v1734953412/sound/bvkld80mplos7nrnhhpb.mp3",
              isPlaying: false,
            },
           
            {
              text: "I am a Real Estate Negotiator specializing in Residential Sales and Rental",
              audioSrc: "https://res.cloudinary.com/alvin-tan/video/upload/v1734953884/sound/zhxwbs1iaecjpvamhmtv.mp3",
              isPlaying: false,
            },
            {
              text: "Do you have other properties that I could assist you in selling or renting?",
              audioSrc: "https://res.cloudinary.com/alvin-tan/video/upload/v1734957013/sound/eb1atyvmwwzc9zpnkqcf.mp3",
              isPlaying: false,
            },]



        }
      ],
    };
  },
  computed: {
    currentVoice() {
      return this.voices[this.currentVoiceIndex];
    },
  },
  methods: {
    switchVoice(index) {
    this.currentVoiceIndex = index;
    this.highlightedSegment = -1;
  },

  toggleAudio(index) {
    const segment = this.currentVoice.textSegments[index];
    const audioPlayer = this.$refs.audioPlayer;

    if (segment.isPlaying) {
      this.stopAudio(index); // Stop the audio and update the play state
    } else {
      audioPlayer.src = segment.audioSrc;
      audioPlayer.play();
      segment.isPlaying = true;

      audioPlayer.onended = () => {
        segment.isPlaying = false; // Set isPlaying to false when audio ends
      };
    }
  },

  stopAudio(index) {
    const audioPlayer = this.$refs.audioPlayer;
    if (audioPlayer) {
      audioPlayer.pause();
      audioPlayer.currentTime = 0; // Reset playback

      // Mark the specific segment as not playing
      this.currentVoice.textSegments[index].isPlaying = false;

      // Reset the highlighted segment if it was the currently playing one
      if (this.highlightedSegment === index) {
        this.highlightedSegment = -1;
      }
    }
  },

}
 
};
</script>

<style>
#app {
  font-family: Avenir, Helvetica, Arial, sans-serif;
  text-align: center;
  color: #2c3e50;
  margin-top: 60px;
}

.button-group {
  margin-bottom: 20px;
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
}

button {
  padding: 10px 20px;
  border: 2px solid #2c3e50;
  border-radius: 5px;
  background-color: white;
  cursor: pointer;
  transition: all 0.3s ease;
}

button.active {
  background-color: #2c3e50;
  color: white;
}

button:hover {
  background-color: #2c3e50;
  color: white;
}

.voice-text-sync {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
}

.segment-content {
  display: flex;
  align-items: center;
  gap: 10px;
}

.voice-text-sync div.highlighted {
  background-color: #2c3e50;
  color: white;
}
</style>
