<template>
  <div>
    <table border="1" cellpadding="10" cellspacing="0">
      <thead>
        <tr style="background:#00ffff">
          <th>NO</th>
          <th>LEAD BY</th>
          <th>DATE GIVE LEAD</th>
          <th>NAME</th>
          <th>NO PHONE</th>
          <th>1ST FOLLOW UP</th>
          <th>REMARKS</th>
        
        </tr>
      </thead>
      <tbody>
        <tr  @dblclick="showPopup(contact)"
          v-for="contact in contacts"
          :key="contact.id"
          :style="{
            textDecoration: shouldStrikeThrough(contact) ? 'line-through' : 'none',
            opacity: shouldStrikeThrough(contact) ? '0.4' : '1'
          }"
        >
          <td >{{ contact.no }}</td>
         
   
          <td >{{ contact.name }}</td>
          <td >{{ contact.phoneNumber }}</td>
          <td><pre>{{ contact.interaction }}</pre></td>
          <td >{{ contact.rating }}</td>
          <td >{{`${contact.rating},${contact.called}:${contact.status}`}}</td>
        
        </tr>
      </tbody>
    </table>

    <div v-if="isPopupVisible" class="popup-overlay" @click="closePopup">
      <div class="popup-content" @click.stop>
        <h2>Contact Details</h2>
        <p><strong>Name:</strong> {{ selectedContact.name }}</p>
        <p><strong>Phone:</strong> {{ selectedContact.phoneNumber }}</p>
        <button @click="closePopup">Close</button>
      </div>
    </div>
  </div>
</template>

<script>
import { ref, onMounted } from "vue";
import { isPhoneDisabled ,loadContacts, formatNumberWithLeadingZeros } from "../utils/contactUtils"; // Adjust the import path


export default {
  setup() {
    const contacts = ref([]);
    const projectFilter = "RSKU Sungai Long"; // Replace with your actual project filter
    const isPopupVisible = ref(false);
    const selectedContact = ref(null);

    const showPopup = (contact) => {
      selectedContact.value = contact;
      isPopupVisible.value = true;
    };

    // Function to load contacts and process them
    const loadAndProcessContacts = async () => {
      try {
        const allContacts = await loadContacts(projectFilter,0);
        contacts.value = allContacts
          .map((contact) => ({
            id: contact.id,
            name: contact.name,
            interaction: contact.interaction,
            no: contact.no,
            sourceDate:contact.sourceDate,
            phoneNumber: contact.phoneNumber.replace("+", "").replaceAll(" ", ""),
            email: contact.email || "",
            status: contact.status || "",
            rating: contact.rating || 0,
            called:contact.called || 0,

          }))
          .sort((a, b) => {
            if (
              formatNumberWithLeadingZeros(a["no"]) <
              formatNumberWithLeadingZeros(b["no"])
            )
              return -1;
            if (
              formatNumberWithLeadingZeros(a["no"]) >
              formatNumberWithLeadingZeros(b["no"])
            )
              return 1;
            return 0;
          });
      } catch (error) {
        console.error("Error loading contacts:", error);
      }
    };

 
    

    // Function to determine if a row should be struck through
    const shouldStrikeThrough = (contact) => {
      // Example condition for strikethrough
      return isPhoneDisabled(contact);
    };

    const closePopup = () => {
      isPopupVisible.value = false;
    };
    // Load contacts on component mount
    onMounted(() => {
      loadAndProcessContacts();
    });

    return {
      contacts,
      showPopup,
      closePopup,
      isPopupVisible,
      selectedContact,
      shouldStrikeThrough
    };
  },
};
</script>

<style scoped>
table {
  border-collapse: collapse;
}

table td,
table th {
  border: 0.5px solid #b9bfca; /* Very thin light gray border */
  padding: 0.5rem; /* Maintain some padding for readability */
}

/* Optional: Add subtle hover effect */
tr:hover {
  background-color: rgba(0, 0, 0, 0.02);
}

.strikethrough {
  text-decoration: line-through;
}

.popup-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
}

.popup-content {
  background: white;
  padding: 1rem;
  border-radius: 8px;
  max-width: 400px;
  width: 90%;
}
</style>
