<template>
    <div>
        <div style="margin-bottom: 20px;">
            <label for="projectNameInput">Project Name: </label>
            <input 
                id="projectNameInput"
                v-model="projectName"
                placeholder="Enter project name"
                style="padding: 8px; width: 200px;"
            />
        </div>

        <h2>Import {{ projectName }}</h2>
       
        <v-btn outlined class="bordered-btn" @click="exportData">
            Import Data
        </v-btn>

        <!-- Progress bar -->
        <div v-if="isExporting" style="margin: 10px 0;">
            <div style="background-color: #f3f3f3; border-radius: 8px; overflow: hidden; height: 24px;">
                <div :style="{ width: progress + '%', backgroundColor: '#4caf50', height: '100%' }"></div>
            </div>
            <p>{{ progress }}% completed</p>
        </div>

        <table @paste="handlePaste">
            <thead>
                <tr>
                    <th v-for="(col, colIndex) in columns" :key="'header-' + colIndex" @click="showColumnSelector(colIndex)">
                        <span>{{ columnMappings[colIndex] || `Column ${colIndex + 1}` }}</span>
                        <v-menu v-model="menu[colIndex]" :close-on-content-click="true">
                            <template v-slot:activator="{ on }">
                                <span v-on="on" style="cursor: pointer; margin-left: 5px;">▼</span>
                            </template>
                            <v-list>
                                <v-list-item 
                                    v-for="field in availableFields" 
                                    :key="field.value"
                                    @click="setColumnMapping(colIndex, field.value)"
                                >
                                    <v-list-item-title>{{ field.text }}</v-list-item-title>
                                </v-list-item>
                            </v-list>
                        </v-menu>
                    </th>
                </tr>
            </thead>
            <tbody>
                <tr v-for="(row, rowIndex) in rows" :key="'row-' + rowIndex">
                    <td v-for="(cell, colIndex) in row" :key="'cell-' + rowIndex + '-' + colIndex">
                        <input v-model="rows[rowIndex][colIndex]" placeholder="Enter data" />
                    </td>
                </tr>
            </tbody>
        </table>

        <div v-if="exportedData.length">
            <h3>Exported Data</h3>
            <pre>{{ exportedData }}</pre>
        </div>
    </div>
</template>

<script>
import { ref } from 'vue';
import { convertDMY2YMD, createOrUpdateContactByKeys } from '../utils/contactUtils';

export default {
    setup() {
        const defaultColumnCount = 10;
        const defaultRowCount = 1000;
        const columns = ref(new Array(defaultColumnCount).fill(1).map((_, i) => i + 1));
        const rows = ref(new Array(defaultRowCount).fill(null).map(() => new Array(defaultColumnCount).fill('')));
        const exportedData = ref([]);
        const progress = ref(0);
        const isExporting = ref(false);
        const projectName = ref('');
        const columnMappings = ref({}); // Store column mappings
        const menu = ref({}); // Control menu visibility for each column

        // Available field options for mapping
        const availableFields = [
            { text: 'None', value: null },
            { text: 'No', value: 'no' },
            { text: 'Name', value: 'name' },
            { text: 'Phone Number', value: 'phoneNumber' },
            { text: 'Address', value: 'address' },
            { text: 'Name 2', value: 'name2' }
        ];

        const showColumnSelector = (colIndex) => {
            menu.value[colIndex] = true;
        };

        const setColumnMapping = (colIndex, field) => {
            if (field === null) {
                delete columnMappings.value[colIndex];
            } else {
                columnMappings.value[colIndex] = field;
            }
            menu.value[colIndex] = false;
        };

        const handlePaste = (event) => {
            event.preventDefault();
            const clipboardData = event.clipboardData.getData('text');
            const rowsData = clipboardData.split('\n').map(row => row.split('\t'));

            rowsData.forEach((rowData, rowIndex) => {
                rowData.forEach((cellData, colIndex) => {
                    if (rowIndex < rows.value.length && colIndex < columns.value.length) {
                        rows.value[rowIndex][colIndex] = cellData;
                    }
                });
            });
        };

        const exportData = async () => {
            if (!projectName.value) {
                alert('Please enter a project name');
                return;
            }

            const formattedDate = new Date().toLocaleDateString("en-GB");
         
            exportedData.value = rows.value.map((row) => {
                const rowData = {
                    source: "Titan",
                    project: projectName.value,
                    sourceDate: convertDMY2YMD(formattedDate),
                    requestType: "buyer"
                };

                // Map data based on column mappings
                row.forEach((cell, colIndex) => {
                    const field = columnMappings.value[colIndex];
                    if (field) {
                        if (field === 'no') {
                            rowData[field] = parseInt(cell);
                        } else {
                            rowData[field] = cell;
                        }
                    }
                });

                return rowData;
            }).filter(row => row.phoneNumber || row.name); // Filter out empty rows

            isExporting.value = true;
            progress.value = 0;

            for (let i = 0; i < exportedData.value.length; i++) {
                const contactData = exportedData.value[i];

                if (contactData.rating === undefined) {
                    contactData.rating = 0;
                }

                contactData.sourceDate = convertDMY2YMD(contactData.sourceDate);
                contactData.rating = parseInt(contactData.rating);
                try {
                    await createOrUpdateContactByKeys(contactData);
                    progress.value = Math.round(((i + 1) / exportedData.value.length) * 100);
                } catch (error) {
                    console.error('Error importing data:', error);
                }
            }

            isExporting.value = false;
            alert('Data exported and sent to Strapi. Check console for details.');
        };

        return {
            projectName,
            rows,
            columns,
            exportedData,
            progress,
            isExporting,
            columnMappings,
            menu,
            availableFields,
            handlePaste,
            exportData,
            showColumnSelector,
            setColumnMapping
        };
    },
};
</script>

<style scoped>
table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 20px;
}

th,
td {
    border: 1px solid #ddd;
    padding: 8px;
}

th {
    cursor: pointer;
    position: relative;
}

input {
    width: 100%;
    padding: 4px;
    box-sizing: border-box;
}

button {
    margin: 5px;
}

.bordered-btn {
    border: 1px solid #ccc;
    border-radius: 5px;
}

.bordered-btn:hover {
    border-color: #1976d2;
}

.bordered-btn:focus {
    box-shadow: 0 0 4px #1976d2;
}
</style>